    "ch4-title": "Chapter 4: 딥러닝의 기초 구조 (5주차)",
    "ch4-intro-title": "1. 오늘 배울 내용",
    "ch4-intro-p1": "이번 주에는 딥러닝 모델 안에 어떤 구조가 있는지 배워요. 간단한 퍼셉트론에서 여러 층을 쓰는 신경망까지 차례로 살펴볼게요.",
    "ch4-intro-p2": "복잡한 수식을 외우기보다 그림에서 정보가 어디로 이동하는지 먼저 확인해 봐요.",

    "ch4-review-title": "2. 지난 시간 복습",
    "ch4-review-p1": "지난 시간에는 여러 데이터를 보고 패턴을 배우는 머신러닝을 배웠어요.",
    "ch4-review-p2": "정답을 주는 지도학습, 정답 없이 묶는 비지도학습, 보상으로 배우는 강화학습을 비교했어요.",
    "ch4-review-p3": "그리고 연습 데이터만 잘 맞히는 과대적합처럼 모델을 평가할 때 주의할 점도 배웠어요.",

    "ch4-perceptron-title": "3. 퍼셉트론의 등장",
    "ch4-perceptron-def": "퍼셉트론은 뇌의 신경세포에서 아이디어를 얻은 간단한 계산 구조예요.",
    "ch4-perceptron-p1": "입력마다 가중치(중요도를 나타내는 숫자)를 곱하고 더해요. 그 결과로 출력을 정해요.",
    "ch4-perceptron-p2": "단순한 경우에는 AND나 OR 같은 논리 문제를 처리할 수 있어요.",

    "ch4-xor-title": "4. XOR 문제와 한계",
