    "ch4-xor-p2": "XOR은 직선 하나로 두 종류를 나누기 어려운 문제이기 때문이에요.",
    "ch4-xor-p3": "<b>XOR:</b> 입력 두 개가 서로 다를 때 1, 같을 때 0이 나오는 규칙이에요.",

    "ch4-mlp-title": "5. 다층 퍼셉트론(MLP)",
    "ch4-mlp-p1": "입력층과 출력층 사이에 '은닉층'을 추가하면 더 복잡한 패턴을 다룰 수 있어요.",
    "ch4-mlp-p2": "은닉층과 비선형 활성화 함수를 사용하면 직선 하나로 나눌 수 없는 패턴도 학습할 수 있어요.",
    "ch4-mlp-p3": "<b>MLP(다층 퍼셉트론):</b> 여러 층을 연결한 신경망이에요.",

    "ch4-backprop-title": "6. 오차역전파",
    "ch4-backprop-p1": "모델이 틀렸을 때 어느 가중치를 얼마나 바꿔야 할까요?",
    "ch4-backprop-p2": "오차역전파는 예측이 얼마나 틀렸는지 계산한 뒤, 각 층의 가중치를 어떻게 바꾸면 좋을지 구하는 방법이에요.",
    "ch4-backprop-p3": "이 값을 참고해 가중치를 조금씩 고치며 학습해요.",

    "ch4-success-title": "7. 딥러닝이 최근에 성공한 이유",
    "ch4-success-1": "학습에 쓸 데이터가 늘어났어요.",
    "ch4-success-2": "GPU 등 계산 장치의 성능이 좋아졌어요.",
