  "ch2-title": "Chapter 2: AI in Business (Week 3)",
 
  "ch2-q1": "1. Why do companies use AI?",
  "ch2-v1": "Cost Reduction",
  "ch2-v2": "Faster work",
  "ch2-v3": "Prediction",
  "ch2-p1": "Companies use AI to save time on repeated tasks, recommend products and estimate future demand.",

  "ch2-q2": "2. Examples of AI Use",
  "ch2-c1": "YouTube: Recommends videos based in part on what you have watched before.",
  "ch2-c2": "Amazon: Uses order data to plan how to store and deliver products.",
  "ch2-c3": "Naver: Uses AI for translation and search.",
  "ch2-c4": "Tesla: Uses cameras to analyze lanes, cars and people near a vehicle.",

  "ch2-data-title": "3. The Most Important Thing for AI",
  "ch2-data-p1": "<b>Good data matters when building AI.</b> Wrong or biased examples can lead to wrong results.",
  "ch2-data-p2": "Think about a model trained only on night photos. It might struggle with photos taken in daylight. Check the quality and variety of the data.",
  "ch2-data-p3": "Before using data, companies need to collect it, check it and organize it.",

