  "ch6-title": "Chapter 6: Create Your Own AI Model (Week 7)",
  "ch6-intro-title": "1. Build your own AI model this week",
  "ch6-intro-p1": "Build a simple image classifier without writing code. You will collect photos, train a model and test it.",
  "ch6-intro-p2": "Follow each step and try the model on photos it has not seen before.",

  "ch6-teachable-title": "2. What is Teachable Machine?",
  "ch6-teachable-desc": "Teachable Machine is a tool from Google. You can train an image model using pictures and test it right away. Varied photos often help the model handle new situations.",

  "ch6-step1-title": "Step 1: Choose Topic & Classes",
  "ch6-step1-p1": "Choose at least two groups (called classes), such as cups and books.",
  "ch6-step1-ex": "For example: rock / paper / scissors, apple / orange, wearing a mask / no mask",

  "ch6-step2-title": "Step 2: Collect Data",
  "ch6-step2-p1": "Take or upload pictures of each group. Try different angles and backgrounds.",

  "ch6-step3-title": "Step 3: Train & Test",
  "ch6-step3-p1": "Click Train, then test the model. The percentages show how the model scores its possible answers, not a guarantee of correctness.",

  "ch6-exam-title": "📝 Midterm assignment information",
  "ch6-exam-item1": "<b>1) Share link:</b> Export the model and copy its shareable link.",
  "ch6-exam-item2": "<b>2) 1–2 page report:</b> Explain the goal, classes, data, correct and incorrect tests, and improvements.",
  "ch6-exam-item3": "<b>3) Extra evidence:</b> Save screenshots of the dataset and confusion matrix. Check MS Teams for requirements and bonus points.",

  "ch6-lab-title": "3. Start Building",
  "ch6-lab-btn": "Open Teachable Machine",
  "ch7-title": "Chapter 7: Data Analysis Basics (Week 9)",
  "ch7-intro-title": "1. How does AI use different kinds of data?",
  "ch7-intro-p1": "AI processes data stored as numbers, lists and tables. How we organize the data can make it easier or harder to analyze.",
  "ch7-intro-p2": "We will compare a single number, a list of numbers, a table and data with more dimensions.",

  "ch7-dim-title": "2. Data shapes: scalar, vector, matrix and tensor",
  "ch7-scalar-t": "Scalar",
  "ch7-scalar-d": "One number. Example: 25",
  "ch7-vector-t": "Vector",
  "ch7-vector-d": "Numbers arranged in a single line. Example: [80, 90, 70]",
  "ch7-matrix-t": "Matrix",
  "ch7-matrix-d": "Numbers in rows and columns. Example: [[1, 2], [3, 4]]",
  "ch7-tensor-t": "Tensor",
  "ch7-tensor-d": "A structure for numerical data with multiple dimensions. Example: a color image (height × width × 3).",

  "ch7-tool-title": "3. Common tools for working with data",
  "ch7-pandas-t": "Pandas",
  "ch7-pandas-d": "Pandas helps you work with rows and columns, like a spreadsheet.",
  "ch7-numpy-t": "NumPy",
  "ch7-numpy-d": "A key Python tool for fast, efficient calculations with large amounts of numerical data.",
  "ch7-plt-t": "Matplotlib",
  "ch7-plt-d": "Matplotlib helps you turn data into charts.",

  "ch7-lab-title": "4. Practice: Work with data yourself",
  "ch7-lab-p1": "In Colab, make a table with Pandas, calculate with NumPy and draw a chart with Matplotlib.",
  "ch7-lab-btn": "Open Google Colab Practice",

  "ch7-summary-title": "5. Key Takeaways",
  "ch7-sum1": "Data can be represented as a single number (scalar), a list (vector), a table (matrix) or a multidimensional array (tensor).",
  "ch7-sum2": "Pandas works with tables, NumPy with numerical calculations and Matplotlib with charts.",
  "ch8-title": "Chapter 8: AI that Remembers Order, RNN (Week 10)",
  "ch8-intro-title": "1. Sequence data: when order matters",
  "ch8-intro-p1": "Order matters in sentences, music and stock prices. We call these sequence data.",
  "ch8-intro-p2": "For example, to guess what comes after “I want to eat…”, a model needs the earlier words.",

  "ch8-rnn-title": "2. RNN: A network that carries information forward",
  "ch8-rnn-desc": "An RNN passes information from one step to the next. What came earlier can affect what happens now.",
  "ch8-rnn-ex": "Example: After reading “I ate…”, an RNN can use those words to predict what might come next, such as “lunch”.",

  "ch8-evolution-title": "3. From RNN to LSTM and Transformer",
  "ch8-lstm-t": "LSTM / GRU",
  "ch8-lstm-d": "LSTM and GRU were designed to help RNNs keep useful information across longer sequences.",
  "ch8-tf-t": "Transformer",
  "ch8-tf-d": "Transformers use attention to find links between words in a sentence. Many modern language models use this design.",

  "ch8-lab-title": "4. Hands-on: How AI Writes",
  "ch8-lab-p1": "Try an RNN that creates handwriting. Watch how the line it drew earlier affects the next line.",
  "ch8-lab-btn": "Try RNN Handwriting",

  "ch8-summary-title": "5. Key Takeaways",
  "ch8-sum1": "Sequence data is data where the order matters, such as sentences or weather measurements over time.",
  "ch8-sum2": "An RNN uses information from earlier steps when calculating the next step.",
  "ch8-sum3": "A Transformer uses attention to calculate relationships between words.",
  "ch9-title": "Chapter 9: Intro to Natural Language Processing (Week 11)",
  "ch9-intro-title": "1. How does a computer work with sentences?",
  "ch9-intro-p1": "Korean, English and other languages we speak are called natural languages. NLP helps computers work with them.",
  "ch9-intro-p2": "A model often splits text into smaller parts and turns them into numbers. It can then search, sort or generate text.",

  "ch9-nlu-title": "2. Two NLP tasks: understanding (NLU) and generation (NLG)",
  "ch9-nlu-t": "NLU (Understanding)",
  "ch9-nlu-d": "NLU means finding what a sentence means or what the user is asking for.",
  "ch9-nlg-t": "NLG (Generation)",
  "ch9-nlg-d": "NLG means producing new text, such as an answer or a summary.",

  "ch9-process-title": "3. Preparing text for a model",
  "ch9-step1-t": "Tokenization",
  "ch9-step1-d": "Tokenization splits text into small pieces called tokens. For example, “I love AI” might become “I”, “love” and “AI”.",
  "ch9-step2-t": "Cleaning & Normalization",
  "ch9-step2-d": "Some systems clean up punctuation or standardize words. Not every model uses the same steps.",

  "ch9-vector-title": "4. Turning text into numbers",
  "ch9-vector-desc": "Computers work with numbers. A model can represent a word with a list of numbers called a vector, such as [0.1, 0.8, -0.5]. Related words may have nearby representations.",

  "ch9-lab-title": "5. Hands-on: AI Word Association",
  "ch9-lab-p1": "Type words into Semantris and see which words the AI considers similar in meaning.",
  "ch9-lab-btn": "Start Semantris",

  "ch9-summary-title": "6. Key points",
  "ch9-sum1": "NLP helps computers analyze or generate text in human languages.",
  "ch9-sum2": "Preparing text, including tokenization, is also important.",
  "ch9-sum3": "Representing words as numerical vectors lets computers calculate relationships between them.",
  "ch10-title": "Chapter 10: Speech Recognition and Speech Generation (Week 12)",
  "ch10-intro-title": "1. How does AI process speech?",
  "ch10-intro-p1": "Speech-to-text (STT) turns spoken words into text. Text-to-speech (TTS) turns text into audio.",
  "ch10-intro-p2": "Today we will learn how AI tries to recognize words when there is background noise.",

  "ch10-stt-title": "2. STT and TTS: speech to text, text to speech",
  "ch10-stt-t": "STT (Speech-to-Text)",
  "ch10-stt-d": "STT turns speech recorded by a microphone into written text.",
  "ch10-tts-t": "TTS (Text-to-Speech)",
  "ch10-tts-d": "TTS creates spoken audio from written text.",

  "ch10-process-title": "3. The 3 Steps of Speech Recognition",
  "ch10-step1-t": "Sampling",
  "ch10-step1-d": "A microphone captures sound. A computer converts it into numbers it can process.",
  "ch10-step2-t": "Feature extraction (spectrogram)",
  "ch10-step2-d": "The system looks at how the sound changes over time. A spectrogram can show these changes.",
  "ch10-step3-t": "Model analysis (sound and language)",
  "ch10-step3-d": "A model uses sound features and sometimes context to estimate the words spoken. Systems use different methods.",

