  "edu11-reflect": "주변 사진에서 어두운 부분과 밝은 부분을 찾아보세요. 흑백 변환과 엣지 검출을 하면 어떤 정보가 두드러질까요?",
  "edu11-s1-title": "촬영·불러오기",
