  "edu11-s2-desc": "색상 채널을 숫자 배열로 표현",
  "edu11-s3-title": "분석·변환",
  "edu11-s3-desc": "엣지 추출, 분류 등 필요한 처리 수행",
  "edu12-lead": "생성형 AI는 글, 그림, 소리를 만들 수 있어요. 이번 주에는 LLM이 문장을 만드는 방식과 RAG가 자료를 찾아 답변에 사용하는 방법을 알아봐요.",
  "edu12-deep": "LLM은 앞에 나온 글과 학습한 패턴을 참고해 다음에 올 토큰을 예측하며 문장을 만들어요. 자연스러운 글이 꼭 사실인 것은 아니에요.",
  "edu12-example": "학교 도서관이 오늘 몇 시까지 열리는지 묻는다고 해 봐요. RAG는 최신 공지문을 찾아 AI 답변에 참고할 수 있어요.",
  "edu12-caution": "RAG는 관련 자료를 찾아 답변 오류를 줄이는 데 도움이 될 수 있어요. 하지만 자료 자체가 틀리거나 오래됐으면 답도 틀릴 수 있어요. 출처를 확인해요.",
  "edu12-flow": "질문부터 검증까지: RAG의 기본 흐름",
  "edu12-caption": "RAG는 하나의 구성 방법이에요. 모든 생성형 AI 시스템이 검색 단계를 사용하는 것은 아닙니다.",
  "edu12-question": "RAG를 사용하면 AI의 답변을 언제나 사실이라고 믿어도 될까요?",
  "edu12-a": "그렇다. 검색을 했으니 반드시 정확하다.",
  "edu12-b": "아니다. 검색된 자료와 답변을 다시 검증해야 한다.",
  "edu12-ok": "정답이에요. RAG가 근거를 제공해도 오류 가능성은 남아 있어요.",
  "edu12-wrong": "검색 자료도 낡거나 잘못될 수 있어요. 중요한 정보는 출처를 확인하세요.",
  "edu12-reflect": "체험 전 기록: 이미지 생성 도구에 같은 주제의 프롬프트를 두 번 입력하고, 어떤 표현을 바꿨을 때 결과가 달라지는지 적어 보세요.",
  "edu12-s1-title": "질문 입력",
  "edu12-s1-desc": "사용자가 질문과 필요한 맥락 제공",
