  "edui-note": "This is a teaching diagram; real systems may be more complex.",
  "edui-quizhow": "Choose an answer to see an explanation right away. Your score is not sent to a server.",
  "edu2-lead": "AI is used in familiar places, from shopping to deliveries. What matters most is the problem it helps solve.",
  "edu2-deep": "First, a company chooses a task. Then it checks what data is available and how the AI result will fit into the work. Buying an AI tool alone does not fix everything.",
  "edu2-example": "A shop can recommend products based on what you looked at or bought. A new customer may get weaker recommendations because the shop has less information.",
  "edu2-caution": "More data is not always better. Wrong or one-sided examples can lead to poor results. Protect personal information too.",
  "edu2-flow": "How a business builds an AI service",
  "edu2-caption": "A simplified service planning cycle. Human oversight and ongoing improvement also matter.",
  "edu2-question": "What should come first when planning an AI recommendation service?",
  "edu2-a": "Define the customer problem and check available data",
  "edu2-b": "Choose the newest AI model regardless of the task",
  "edu2-ok": "Correct. First decide which problem to solve and check whether you have the necessary data.",
  "edu2-wrong": "Try again. Without a defined problem, even an advanced model may not deliver a useful result.",
  "edu2-reflect": "Think about it: identify one repetitive task at school or at work. What could AI help with, and what should a person still check?",
  "edu2-s1-title": "Define the problem",
  "edu2-s1-desc": "Identify customer needs or a slow, repetitive task",
  "edu2-s2-title": "Prepare the data",
  "edu2-s2-desc": "Check its quality and whether it may be used",
  "edu2-s3-title": "Apply and evaluate",
  "edu2-s3-desc": "Measure whether recommendations or predictions help",
  "edu3-lead": "Machine learning finds patterns in examples and tries them on new data. We will look at types of learning and ways to test the results.",
  "edu3-deep": "A student may memorize practice questions but still struggle on a new test. AI can do the same. That is why we test a model on data it did not train on.",
  "edu3-example": "Imagine an AI that says whether you need an umbrella tomorrow. It learns from earlier weather and rain records, then predicts the next day. You can compare the prediction with what happened.",
  "edu3-caution": "Accuracy alone can hide important mistakes. For example, when screening for a rare illness, missed cases matter too. Precision and recall help show this.",
  "edu3-flow": "The basic training and evaluation cycle",
  "edu3-caption": "Keeping training separate from evaluation is the main idea. This is a simplified learning diagram.",
  "edu3-question": "Is a model good simply because it fits its training data?",
  "edu3-a": "Yes. Perfect scores on seen examples are enough.",
  "edu3-b": "No. We should test how well it handles unseen data.",
  "edu3-ok": "Correct. Test the model on data it did not train on to see how well it handles new cases.",
  "edu3-wrong": "A model can memorize its examples. Consider why we keep separate test data.",
  "edu3-reflect": "Try it: “spam / not spam” is classification. Predicting tomorrow’s temperature, such as 23°C, is a number prediction.",
  "edu3-s1-title": "Prepare examples",
  "edu3-s1-desc": "Collect inputs and labels if the task needs them",
