  "edu3-s3-desc": "Check performance on previously unseen examples",
  "edu4-lead": "A neural network joins several calculation steps. We will use a diagram to see how a perceptron works and why layers help.",
  "edu4-deep": "A perceptron multiplies each input by a weight and adds them up. Without a hidden layer, it cannot separate patterns such as XOR using one straight line.",
  "edu4-example": "Imagine two switches: the light turns on only when one switch is on and the other is off. That is XOR. A network with hidden layers can learn this pattern.",
  "edu4-caution": "More layers do not always help. The data, training settings and computing cost also matter.",
  "edu4-flow": "How a multilayer network processes input",
  "edu4-caption": "Backpropagation calculates how to adjust weights using prediction error. This diagram is much simpler than a real network.",
  "edu4-question": "What helps a network represent non-linear patterns such as XOR?",
  "edu4-a": "Hidden layers and non-linear activation functions",
  "edu4-b": "Deleting all of the input values",
  "edu4-ok": "Correct. Hidden layers with non-linear transformations can model more complex boundaries.",
  "edu4-wrong": "Try again. The goal is to expand what the model can represent, not to remove its inputs.",
  "edu4-reflect": "Before trying Playground: predict how changing the number of hidden layers may affect learning, and explain why.",
  "edu4-s1-title": "Input layer",
