  "w5-eyebrow": "НЕДЕЛЯ 05 · ГЛАВА 4",
  "w5-hero-title": "Почему одного перцептрона было недостаточно?",
  "w5-hero-desc": "Краткое повторение устройства перцептрона, проблемы XOR (1-я зима ИИ), скрытых слоёв и многослойного перцептрона (MLP), обратного распространения ошибки и практики в TensorFlow Playground.",
  "w5-nav-1": "1. Нейрон и перцептрон",
  "w5-nav-2": "2. AND · OR · XOR",
