  "w5-p1-title": "1. Входы (X) × Веса (W)",
  "w5-p1-desc": "У каждого фактора своя важность, поэтому входы умножаются на <b>веса (Weights)</b>.<br>(Например, для пикника погода важнее = <b>0.8</b>, а закуски = <b>0.2</b>)",
