  "w5-p3-title": "3. Порог → Выход (1 или 0)",
  "w5-p3-desc": "Если сумма превышает порог (Threshold), на выходе <b>1 (Идём на пикник! ДА)</b>, иначе — <b>0 (Остаёмся дома! НЕТ)</b>.",
  "w5-sim1-title": "☀️ Проверьте сами: идём ли завтра на пикник? (Калькулятор перцептрона)",
  "w5-sim1-desc": "Вес погоды = 0.8, вес закусок = 0.2, порог = 0.7. Нажимайте на кнопки, чтобы увидеть решение.",
