  "w5-sim1-out2": "Расчёт: (1 × 0.8) + (0 × 0.2) = 0.8 (≥ 0.7) → Выход 1: Погода имеет большой вес (0.8), поэтому идём на пикник даже без закусок! ☀️",
  "w5-sim1-out3": "Расчёт: (0 × 0.8) + (1 × 0.2) = 0.2 (< 0.7) → Выход 0: В плохую погоду остаёмся дома даже с вкусной едой. 🌧️",
  "w5-s2-title": "2. 1-й бум ИИ (AND · OR) и проблема XOR, вызвавшая 1-ю зиму ИИ",
  "w5-s2-desc": "Однослойный перцептрон проводит <b>только одну прямую линию</b>. Он легко решил задачи <b>OR</b> и <b>AND</b> (вызвав <b>1-й бум ИИ</b>), но не смог разделить одной прямой диагональные точки <b>XOR</b> — началась <b>1-я зима ИИ</b>.",
  "w5-sim2-title": "📐 Сравните наглядно: можно ли разделить точки одной прямой? (OR · AND vs XOR)",
