  "w5-sim2-out3": "❌ Проблема XOR: даёт 1 только тогда, когда входы различаются (если оба 1 — выход 0). Точки лежат по диагонали, и ни одна одиночная прямая не может их разделить! (Решается кривыми границами в MLP!)",
  "w5-tbl-in1": "Вход X₁",
  "w5-tbl-in2": "Вход X₂",
  "w5-tbl-or": "OR (Хотя бы один 1)",
