  "w10-sim2-out3": "📢 출력 게이트 (Output Gate): 휴지통에 버릴 건 버리고 금고에 모아둔 핵심 과거 기억과 현재 정보를 조합해, \"이번 빈칸의 최종 정답은 이 단어야!\"라고 확성기로 외쳐줍니다.",
  "w10-sim2-out4": "⚡ GRU (Update + Reset Gate): LSTM의 망각+입력 게이트를 하나로 합친 '업데이트 게이트(Update Gate)'와 과거 기억을 정리하는 '리셋 게이트(Reset Gate)' 2개만 사용하여, LSTM과 거의 같은 기억력을 훨씬 가볍고 빠르게 구현했습니다!",
  "w10-s3-title": "3. 현대 AI의 최종 끝판왕 '트랜스포머(Transformer)'와 4대 모델 진화 비교표",
  "w10-s3-desc": "RNN·LSTM·GRU의 '한 줄 서서 기다리기' 한계를 완전히 깨부수고, 오늘날 <b>ChatGPT</b>(GPT의 마지막 <b>T = Transformer</b>)와 현대 생성형 AI를 탄생시킨 혁명적 주인공입니다.",
