  "w10-eyebrow": "WEEK 10 · CHAPTER 8",
  "w10-hero-title": "How Does AI Remember Order and Understand Sentences & Music?",
  "w10-hero-desc": "A concise review of Sequence Data (sentences, music, stock prices, weather), RNN's relay-baton memory, LSTM's 3 Gatekeepers & GRU's 2-gate diet, and the ultimate powerhouse behind ChatGPT: the Transformer.",
