  "w10-s1-title": "1. Sequence Data (Where Order Matters) & RNN: The AI That Remembers",
  "w10-s1-desc": "Week 09 Review: <b>A color image is a 3D Tensor</b> (Width × Height × 3 RGB channels), and the Data Pipeline flows from <b>Raw Data → Pandas (Organize) → NumPy (Calculate) → Matplotlib (Visualize)</b>. Now, how does AI handle data that moves over time where <b>order is everything</b>?",
  "w10-seq-badge": "Data Where Order is Crucial",
  "w10-seq-title": "① Sequence Data",
