  "w10-rnn-badge": "One-Way DNN vs. Looped RNN",
  "w10-rnn-title": "② Recurrent Neural Network (RNN)",
  "w10-rnn-body": "• <b>General Neural Network (DNN):</b> One-way flow with no memory—forgets each word right after reading it.<br>• <b>RNN's Secret:</b> Has a <b>curved loop arrow</b> that mixes the <b>new word</b> with the <b>memory note (Hidden State)</b> from the previous step!",
  "w10-sim1-title": "🏃 Try It: RNN's 3-Step Relay Baton Memory & Context Disambiguation",
  "w10-sim1-desc": "Follow the prepared RNN example in the order 'I → ate → lunch', then explore the context of 'spring'. A hidden state is a vector of numbers; the 'memory note' is an analogy.",
  "w10-sim1-btn1": "Step 1 · Read 'I' → hidden state h₁",
  "w10-sim1-btn2": "Step 2 · Read 'ate' + h₁ → h₂",
  "w10-sim1-btn3": "Step 3 · Read 'lunch' + h₂ → h₃",
  "w10-sim1-btn4": "Context Check · What does 'spring' mean in \"I love flowers in spring\"?",
  "w10-sim1-out1": "Step 1: RNN reads 'I' and computes hidden state h₁, a vector of numbers. A 'note about I' is an analogy for the information passed to the next step.",
  "w10-sim1-out2": "Step 2: RNN reads 'ate' and uses the previous hidden state h₁ to compute h₂. The new state carries information from the sequence 'I → ate' to the next step.",
  "w10-sim1-out3": "Step 3: RNN reads 'lunch' and uses h₂ to compute h₃. This numeric vector reflects information from 'I → ate → lunch'; the memory-note wording illustrates that process.",
  "w10-sim1-out4": "🌸 Context Power: Looking at 'spring' alone, AI cannot tell if it means a metal coil or the warm season. Because RNN keeps 'flowers' in its memory note, it knows 'spring' means the warm season!",
  "w10-s1-sub": "🌍 4 Everyday Areas Where RNN's Memory Shines",
  "w10-app1-t": "1. Machine Translators (Google · Papago)",
