  "w10-s2-title": "2. Two Fatal Problems of RNN & The Rescuers: LSTM (3 Gates) and GRU (2 Gates)",
  "w10-s2-desc": "Basic RNNs suffered from two major weaknesses on long sequences, leading scientists to invent <b>LSTM</b> and <b>GRU</b>.",
  "w10-lim1-badge": "Problem 1 · The Vanishing Gradient",
  "w10-lim1-title": "❌ Memory Fades Away Like Wet Ink on Long Sentences",
  "w10-lim1-body": "\"I went to school yesterday morning, then I ate delicious pasta, and watched a fun movie at home.\"<br>As information travels forward, early words fade away. If asked <b>\"When did you go to school?\"</b>, the RNN has already forgotten <i>\"yesterday morning\"</i>.",
  "w10-lim2-badge": "Problem 2 · Slow Sequential Speed",
  "w10-lim2-title": "⏳ Every Word Must Wait in Line (No Parallel Math)",
  "w10-lim2-body": "Like a relay race, RNN cannot move to the next word until it finishes calculating the previous word and note. <b>Parallel calculation is impossible</b>, making it very slow on large books or documents.",
  "w10-lstm-badge": "Rescuer 1 · Selection & Concentration (Safe 🔐 + Trash Can 🗑️)",
