  "w10-gru-badge": "Rescuer 2 · Simple LSTM ([3 Gates] - [1 Gate] = [2 Gates])",
  "w10-gru-title": "② GRU (Gated Recurrent Unit · 2-Gate Diet)",
  "w10-gru-body": "Puts the heavy 3-gate LSTM on a diet! Merges the Forget and Input gates into a single <b>Update Gate</b> plus a <b>Reset Gate</b> (2 gates total)—delivering nearly identical memory retention to LSTM, but much lighter and faster!",
  "w10-sim2-title": "🔐 Try It: Inside LSTM's 3 Gatekeepers & GRU's 2-Gate Diet",
  "w10-sim2-desc": "Click each gate below to see how LSTM and GRU filter, save, and output context.",
  "w10-sim2-btn1": "1. Forget Gate (Trash Can 🗑️)",
  "w10-sim2-btn2": "2. Input Gate (Memory Safe 🔐)",
  "w10-sim2-btn3": "3. Output Gate (Megaphone 📢)",
  "w10-sim2-btn4": "4. GRU's 2 Gates (Update & Reset ⚡)",
  "w10-sim2-out1": "🗑️ Forget Gate: Evaluates past data and erases irrelevant old details into the trash can to free up brain capacity when the topic changes.",
  "w10-sim2-out2": "🔐 Input Gate: Evaluates brand-new data and locks crucial new clues safely inside the long-term memory safe.",
  "w10-sim2-out3": "📢 Output Gate: Combines filtered past memories from the safe with present data to shout out the definitive answer for the current step.",
  "w10-sim2-out4": "⚡ GRU (Update + Reset Gate): Merges Forget + Input into one 'Update Gate' and uses a 'Reset Gate' (only 2 gates!). Like a slim modern smartphone, it keeps LSTM's long memory while running much faster!",
  "w10-s3-title": "3. The Ultimate Powerhouse: Transformer & The 4-Model Evolution Table",
  "w10-s3-desc": "Breaking through the sequential waiting limits of RNN, LSTM, and GRU, the <b>Transformer</b> is the revolutionary brain inside <b>ChatGPT</b> (the <b>'T'</b> in GPT stands for <b>Transformer</b>!).",
  "w10-old-badge": "The Old Way · Reading Word by Word with a Magnifying Glass",
  "w10-old-title": "🔍 Sequential Models (RNN · LSTM · GRU)",
