  "w10-tf-title": "📸 Transformer (Attention Mechanism + Parallel Processing)",
  "w10-tf-body": "• <b>Parallel Processing:</b> Looks at the <b>entire sentence all at once</b>—calculating all words simultaneously at lightning speed.<br>• <b>Attention Mechanism:</b> Connects the first word and last word like a real-time spiderweb for profound contextual understanding!",
  "w10-tbl-col1": "Model (Student Analogy)",
