  "w10-tbl-col4": "Core Mechanism & Characteristics",
  "w10-r1-c1": "① RNN (Pointing word-by-word)",
  "w10-r1-c2": "Short",
  "w10-r1-c3": "Slow (Sequential)",
  "w10-r1-c4": "Passes a memory baton step by step, but forgets the beginning when sentences get long (Vanishing Gradient)",
  "w10-r2-c1": "② LSTM (Carrying a heavy safe)",
  "w10-r2-c2": "Long",
  "w10-r2-c3": "Heavy / Slow",
  "w10-r2-c4": "Uses 3 Gatekeepers (Forget, Input, Output) to lock key clues in a safe for long memory, but heavy to compute",
  "w10-r3-c1": "③ GRU (Slim, light bag)",
  "w10-r3-c2": "Long",
