  "w11-pipe-note": "🍳 <b>The 5-Step NLP Pipeline (Like Cooking):</b> <b>1. Collection</b> (Gather raw text ingredients) → <b>2. Preprocessing*</b> (Clean & chop data — <b>determines 80% of AI performance!</b>) → <b>3. Feature Extraction</b> (Transform text into number vectors) → <b>4. Model Training</b> (Feed into Transformer/RNN) → <b>5. Result Analysis</b> (Verify accuracy)",
