  "w11-sim1-btn3": "Step 3 · Normalization (Unifying Forms 📏)",
  "w11-sim1-out1": "🍕 Step 1 Tokenization (Attendance Quiz Key!): Slices a long sentence into bite-sized minimum units called 'Tokens' so AI can process them (e.g., \"I love AI\" → [\"I\", \"love\", \"AI\"]; Korean also separates attached particles).",
