  "w12-sim1-btn5": "Step 5 · Language Modeling",
  "w12-sim1-out1": "🔢 Step 1 Digitization (Sounds to Numbers): The microphone cuts continuous analog sound waves into microscopic digital numbers.",
  "w12-sim1-out2": "🌈 Step 2 Feature Extraction (Finding Key Features): Removes background noise and maps frequencies into a visual 'Spectrogram'—a calculable fingerprint of the voice.",
