  "w13-sim2-out1": "📐 에지 검출 (Edge Detection): 밝기 숫자가 급변하는 자동차·보행자·건물의 테두리 선만 하얗게 남기고 나머지 색상 픽셀은 모두 지워, 데이터 계산량을 획기적으로 줄여줍니다.",
  "w13-sim2-out2": "🏷️ 1단계 이미지 분류 (Classification — \"What is it?\"): 사진 전체에 대해 \"이 사진은 자동차(CAR) 사진입니다!\"라고 이미지 전체 수준의 카테고리 이름표를 붙여줍니다.",
  "w13-sim2-out3": "📦 2단계 객체 탐지 (Object Detection — \"What and where?\"): 사진 속 왼쪽의 자동차(92%)와 오른쪽의 보행자(90%)가 각각 어디에 있는지 네모난 경계 상자(Bounding Box)로 콕 집어 표시합니다.",
  "w13-sim2-out4": "🎨 3단계 이미지 분할 (Segmentation — \"What are the exact borders?\"): 사각형 박스를 넘어 자동차와 보행자에 해당하는 정확한 픽셀 테두리(Pixel-level mask)만 오려내듯 정밀하게 색칠합니다!",
  "w13-s3-title": "3. 핵심 기술: CNN · OpenCV 라이브러리 · 과적합을 막는 데이터 증강(Data Augmentation)",
  "w13-s3-desc": "출석 퀴즈 1·2번의 주인공인 <b>CNN</b>과 <b>데이터 증강(Data Augmentation)</b>, 그리고 현업 표준 도구인 <b>OpenCV</b>의 역할을 정리해 봅시다.",
  "w13-k1-title": "1. CNN (합성곱 신경망 · 퀴즈 1 정답!)",
  "w13-k1-desc": "<b>왜 컴퓨터 비전에서 중요할까?</b><br>사람이 일일이 규칙을 짜지 않아도 <b>이미지의 핵심 특징(Features)과 2차원 공간적 패턴(Spatial Patterns)을 스스로 학습</b>하기 때문입니다!",
  "w13-k2-title": "2. OpenCV (오픈씨비 라이브러리)",
  "w13-k2-desc": "<b>전 세계 표준 영상 처리 도구!</b><br>빠른 C++ 기반으로 파이썬과 완벽 연동되며, 흑백 변환·가우시안 블러·에지 검출 같은 <b>행렬 수학 연산을 단 한 줄의 함수</b>로 처리합니다.",
  "w13-k3-title": "3. 데이터 증강 (Data Augmentation · 퀴즈 2 정답!)",
  "w13-k3-desc": "<b>1장의 사진을 수십 장의 변형 사진으로!</b><br>사진을 회전·반전·확대·밝기 조절하여 <b>다양한 학습 데이터를 만들고, 과적합(Overfitting)을 막아 실전 성능을 높입니다!</b>",
  "w13-aug-box-title": "🐱 직접 눌러보기: 고양이·앵무새 사진 1장으로 수십 장을 만드는 '데이터 증강' 원리",
  "w13-aug-box-desc": "슬라이드 14·19쪽의 데이터 증강(Data Augmentation) 변환 기법 버튼을 눌러 왜 이 작업이 과적합(Overfitting)을 막아주는지 확인해 보세요.",
  "w13-aug-btn1": "1. 회전 (Rotate · angle=45°)",
  "w13-aug-btn2": "2. 좌우 반전 (Flip Horizontal)",
  "w13-aug-btn3": "3. 밝기·확대 조절 (Brightness & Zoom)",
  "w13-aug-out1": "🔄 회전 (rotate): 사진을 45도 살짝 기울여도 여전히 같은 고양이(또는 앵무새)임을 가르쳐, 실전에서 고개를 갸우뚱한 고양이를 만나도 정확히 인식하게 합니다.",
  "w13-aug-out2": "🪞 좌우 반전 (flip_horizontal): 거울에 비친 것처럼 좌우를 뒤집어 새로운 방향의 학습 데이터를 만듭니다. 돈과 시간을 들여 새로 촬영하지 않고도 데이터가 2배로 늘어납니다!",
  "w13-aug-out3": "💡 밝기·확대 조절 (adjust_brightness / zoom): 어두운 방에서 찍힌 것처럼 밝기를 낮추거나(factor=0.8) 얼굴을 확대해, AI가 작은 노이즈나 조명 조건만 통째로 외워버리는 '과적합(Overfitting)'을 완벽히 예방합니다! (출석 퀴즈 2 핵심)",
  "w13-s4-title": "4. 실습: Google Colab에서 OpenCV로 이미지 행렬 연산하기",
