  "w13-code-explain": "💡 OpenCV 핵심 함수 4가지: <b>cv2.imread()</b> = 사진을 숫자 행렬로 읽기 · <b>img.shape</b> = (세로, 가로, 채널) 크기 확인 · <b>cv2.cvtColor(..., cv2.COLOR_BGR2GRAY)</b> = 3D 컬러 텐서를 2D 흑백 행렬로 압축 · <b>cv2.GaussianBlur(img, (5,5), 0)</b> = 주변 5×5 픽셀 평균을 내어 부드럽게 노이즈 제거",
