  "w13-q1-q": "Q1. [출석 퀴즈 1] 컴퓨터 비전(Computer Vision)에서 CNN(합성곱 신경망)이 중요한 이유는 무엇인가요? (Why is CNN important in Computer Vision?)",
  "w13-q1-a": "텍스트 데이터만 처리할 수 있기 때문",
