  "w13-q1-why": "CNN은 합성곱을 이용해 이미지의 국소적인 특징과 공간적 패턴을 학습할 수 있어 이미지 분석에 활용됩니다.",
  "w13-q2-q": "Q2. [출석 퀴즈 2] 사진을 회전·반전·확대·밝기 조절하는 '데이터 증강(Data Augmentation)'의 가장 주된 목적은 무엇인가요? (What is the main purpose of Data Augmentation?)",
  "w13-q2-a": "정답 라벨을 유지한 변형으로 학습 데이터를 다양하게 하고 성능 개선을 돕기 위해",
