  "w13-q3-q": "Q3. 컴퓨터 비전의 3대 핵심 과제 중, 사각형 박스로 위치를 잡는 수준을 넘어 '픽셀 단위 마스크(Pixel-level masks)'로 사물의 정확한 테두리 윤곽만 오려내듯 색칠해 주는 가장 정밀한 작업은?",
  "w13-q3-a": "이미지 분할 (Image Segmentation — \"What are the exact borders?\")",
  "w13-q3-b": "이진 바코드 스캔 (Binary Barcode Scanning)",
  "w13-q3-why": "무엇인지 맞히는 것은 분류(Classification), 박스로 위치를 잡는 것은 객체 탐지(Object Detection), 픽셀 단위로 정확한 경계를 오려내는 것은 이미지 분할(Segmentation)입니다!",
  "w13-q4-q": "Q4. OpenCV에서 컬러 이미지 img를 그레이스케일로 바꾸는 명령어와, 주변 5×5 픽셀에 가우시안 가중치를 적용한 평균으로 이미지를 부드럽게 만드는 명령어의 올바른 짝은?",
  "w13-q4-a": "흑백 변환: plt.show() / 블러: np.arange(12)",
