  "w14-s2-desc": "글을 이해하고 쓰는 <b>어텐션과 LLM</b>, 그리고 그림을 그리는 <b>GAN과 디퓨전(Diffusion)</b>의 작동 원리를 비교해 봅시다.",
  "w14-att-badge": "트랜스포머의 핵심 · 단어 관계 거미줄",
  "w14-att-title": "① 어텐션 (Attention) & 거대 언어 모델 (LLM)",
  "w14-att-body": "• <b>어텐션(Attention):</b> 문장을 한 단어씩 읽지 않고 <b>문장 전체를 동시에 훑으며 단어 사이의 수학적 친밀도를 계산</b>합니다. <i>\"The animal didn't cross the street because <b>it</b> was too tired.\"</i>에서 피곤한 주체인 it = animal(동물)임을 정확히 연결합니다!<br>• <b>LLM (ChatGPT, Gemini):</b> 수억 개의 문장을 읽고 <b>'다음에 올 가장 확률 높은 단어 맞히기'</b>(오늘 날씨가... → 좋다 80%, 춥다 15%, 덥다 5%)를 반복 훈련해 문법과 문맥을 깨우친 거대 언어 뇌입니다.",
  "w14-llm-badge": "ChatGPT가 똑똑하고 예의 바른 비서가 되기까지",
  "w14-llm-title": "② LLM을 완성하는 3단계 훈련 계단",
  "w14-llm-body": "1. <b>사전 학습 (Pre-training):</b> 인터넷의 수억 개 문장을 읽으며 다음 단어 확률을 계산해 기초 문법과 상식을 배웁니다.<br>2. <b>미세 조정 (Fine-tuning):</b> 사람이 만든 질문·답변(Q&A) 모음집으로 친절하게 대화하는 패턴을 배웁니다.<br>3. <b>RLHF (인간 피드백 기반 강화 학습):</b> AI의 여러 답변 중 사람이 <b>안전하고 자연스러운 답변에 칭찬(보상)</b>을 주어 정중하게 다듬습니다.",
  "w14-tbl-col1": "이미지 생성 모델",
  "w14-tbl-col2": "핵심 원리 및 비유",
  "w14-tbl-col3": "작동 방식 및 완성 기준",
  "w14-r1-c1": "③ GAN (적대적 생성 신경망)",
  "w14-r1-c2": "<b>위조지폐범(생성자) vs 경찰(판별자)의 대결!</b><br>두 개의 AI가 수만 번 경쟁하며 실력을 키움",
  "w14-r1-c3": "• <b>생성자(Generator):</b> 가짜 그림을 그려 경찰을 속임<br>• <b>판별자(Discriminator):</b> 진짜와 가짜를 100% 가려내려 감시<br>• <b>완성 기준:</b> 판별자가 진짜/가짜를 구별할 확률이 동전 던지기 같은 <b>50%로 수렴할 때(완벽히 속았을 때) 학습 완료!</b>",
  "w14-r2-c1": "④ Diffusion (디퓨전 · 확산 모델)",
  "w14-r2-c2": "<b>모래바람(노이즈) 속에서 조각품 깎아내기!</b><br>최근 고화질 이미지 생성 AI의 주류 기술",
  "w14-r2-c3": "• <b>파괴 과정(Forward):</b> 각설탕이 물에 녹듯 깨끗한 사진에 노이즈 점들을 더해 완전히 뭉개지는 과정을 학습<br>• <b>생성 과정(Reverse · Denoising):</b> <b>무작위 노이즈 점들에서 시작해 프롬프트 조건에 맞춰 노이즈를 단계별로 지워나가며(청소하며)</b> 선명한 그림 완성!",
  "w14-sim2-title": "🧠 직접 비교하기: 생성형 AI 4대 핵심 기술 (Attention · LLM · GAN · Diffusion)",
  "w14-sim2-desc": "버튼을 눌러 슬라이드 7~11쪽의 각 기술이 작동하는 핵심 장면을 확인해 보세요.",
  "w14-sim2-btn1": "1. 어텐션 (Attention · 'it = animal')",
  "w14-sim2-btn2": "2. LLM (다음 단어 확률 예측 & 3단계 훈련)",
  "w14-sim2-btn3": "3. GAN (위조범 vs 경찰 · 50% 수렴)",
  "w14-sim2-btn4": "4. 디퓨전 (Diffusion · 노이즈 제거 조각술)",
  "w14-sim2-out1": "🕸️ 어텐션 (Attention): \"The animal didn't cross the street because it was too tired.\" → 문장 전체를 한눈에 보고 'tired(피곤한)'와 가장 연관이 깊은 'animal(동물)'에 파란 시선 줄을 강하게 연결해 'it = 동물'임을 알아냅니다!",
  "w14-sim2-out2": "📊 LLM (대규모 언어 모델): \"The weather today is...\" 뒤에 올 단어로 Good[80%], Cold[15%], Hot[5%] 확률을 계산해 문장을 이어가며, 사전학습(Pre-training) → 미세조정(Fine-tuning) → 인간 피드백 강화학습(RLHF) 3단계를 거쳐 완성됩니다.",
  "w14-sim2-out3": "⚔️ GAN (적대적 생성 신경망): 가짜 그림을 그리는 생성자(Forger)와 진짜를 가려내는 판별자(Judge)가 끝없이 경쟁합니다. 판별자가 진짜와 가짜를 구별할 확률이 50%(동전 던지기)가 될 만큼 완벽한 그림이 나오면 학습이 끝납니다!",
  "w14-sim2-out4": "🌫️➡️🖼️ 디퓨전 (Diffusion 모델): 학습할 때는 사진에 노이즈를 뿌려 망가뜨리는 법을 배우고, 실전 생성 때는 거꾸로 '무작위 노이즈 점 구름'에서 시작해 프롬프트 조건에 맞춰 노이즈를 한 겹씩 닦아내며(Denoising) 선명한 그림을 조각해 냅니다!",
  "w14-s3-title": "3. 멀티모달(Multimodal) AI와 치명적 한계 '환각(Hallucination)'을 막는 RAG",
  "w14-s3-desc": "글·그림·소리를 동시에 다루는 <b>멀티모달 엔진</b>의 활약과, AI의 거짓말인 <b>환각 현상</b>을 해결하는 <b>RAG(출석 퀴즈 정답!)</b>를 살펴봅시다.",
  "w14-mm-badge": "Text + Image + Audio + Video 통합 엔진",
  "w14-mm-title": "① 멀티모달 AI (Multimodal AI)",
  "w14-mm-body": "• 글자만 다루거나 그림만 다루는 수준을 넘어 <b>텍스트, 이미지, 음성, 영상을 동시에 이해하고 처리</b>합니다.<br>• 예: 삐뚤빼뚤한 손그림 스케치 + <i>\"멋진 미래형 스피커로 바꿔줘\"</i> → 즉시 3D 디자인 시안 완성!<br>• <b>활약 분야:</b> 디자인(스케치→시안), 엔터테인먼트(게임 에셋·영화 효과), 패션(트렌드 분석·신규 패턴), 마케팅·광고·교육",
  "w14-rag-badge": "환각(Hallucination) 해결사 · 출석 퀴즈 정답!",
  "w14-rag-title": "② 환각(Hallucination) 현상과 해결책 RAG (검색 증강 생성)",
  "w14-rag-body": "• <b>환각(Hallucination · AI의 거짓말):</b> 생성형 AI는 사실을 '아는' 것이 아니라 확률적으로 그럴듯한 단어를 이어 붙이기 때문에, <b>없는 논문·가짜 판례·틀린 회사 규정을 진짜처럼 당당하게 지어낼 위험</b>이 있습니다 (인간의 사실 검증 필수!).<br>• <b>해결책 RAG (Retrieval-Augmented Generation):</b> AI가 내 기억만 믿고 답하기 전에 <b>신뢰할 수 있는 외부/내부 문서 데이터베이스(회사 사규 금고 등)를 먼저 검색(Retrieve)한 뒤, 그 근거를 바탕으로 정확한 답변을 생성(Generate)</b>하는 기술입니다!",
  "w14-sim3-title": "🔍 직접 비교하기: 일반 LLM(환각 위험) vs RAG 검색 증강 생성(출석 퀴즈 핵심!)",
  "w14-sim3-desc": "질문: \"우리 회사 연차 휴가 규정이 어떻게 돼?\" (또는 \"달은 무엇으로 만들어졌어?\")에 대해 두 방식이 어떻게 다르게 답하는지 눌러보세요.",
  "w14-sim3-btn1": "1. 일반 LLM (내부 기억만 의존 → 환각 발생!)",
  "w14-sim3-btn2": "2. RAG 적용 LLM (외부/내부 신뢰 문서 검색 후 생성!)",
  "w14-sim3-out1": "⚠️ 일반 LLM (Hallucination 위험!): 사내 규정 문서를 보지 않고 내부 기억 가중치만으로 그럴듯한 말을 이어 붙여 \"아무 때나 당일 아침에 신청해도 됩니다\" 또는 \"달은 초록 치즈로 만들어졌습니다\" 같은 당당한 거짓말(환각)을 지어낼 수 있습니다!",
  "w14-sim3-out2": "✅ RAG (Retrieval-Augmented Generation · 출석 퀴즈 정답!): 1) 먼저 사내 규정 DB(Specific Knowledge Base)에서 '연차 규정 문서'를 검색(Retrieve)하고 → 2) 질문과 검색된 문서를 합쳐 → 3) \"사규 제12조에 따라 사용 3일 전까지 신청해야 합니다\"처럼 근거 있는 정확한 답을 생성합니다! (장점: ① 정확성 향상, ② 거대 모델 재학습 없이 최신 정보 즉시 반영 및 비용 절감, ③ 사내 기밀 보안 유지)",
