  "w14-prac-note": "🧪 <b>프롬프트 실습 3단계:</b> ① \"A cute robot drinking coffee\" (대상+행동) → ② \"A cute robot drinking coffee in space\" (+배경) → ③ \"A cute robot drinking coffee in space, watercolor style\" (+스타일). 마음에 들지 않으면 \"more realistic\", \"3D render\", \"cinematic lighting\", \"minimalist style\"을 붙여 변화를 비교해 보세요!",
  "w14-chatgpt-btn": "ChatGPT 생성 실습 열기 ↗",
