  "w14-exam-body": "• <b>시험 범위 (Scope):</b> <b>9주차 ~ 14주차 (Chapters 9 – 14</b> · 데이터 분석 기초, RNN·트랜스포머, 자연어 처리 NLP, 음성 AI, 컴퓨터 비전, 생성형 AI)<br>• <b>문제 유형 (Question Types):</b> <b>4지 선다형 객관식 (Multiple choice, 4 options) & 짧은 단답형 (Short-answer questions)</b><br>• <b>진행 장소 및 일시 (Test Duration):</b> <b>MS Teams &gt; Assignments(과제) 탭</b> (슬라이드 안내: June 12, 18:00–21:00 · <i>지각 제출 시 감점될 수 있으니 반드시 MS Teams 공지와 마감 시간을 확인하세요!</i>)",
  "w14-quiz-title": "5. 이해도 확인 퀴즈 (5문항 · 14주차 출석 퀴즈 완벽 수록)",
  "w14-q1-q": "Q1. [출석 퀴즈] AI가 그럴듯한 거짓말을 지어내는 '환각(Hallucination)' 현상을 막기 위해, 외부 데이터베이스나 신뢰할 수 있는 내부 문서를 먼저 검색한 뒤 이를 근거로 답변을 생성하는 기술은 무엇인가요? (What is the technology that searches external databases to generate answers in order to prevent AI hallucination?)",
  "w14-q1-a": "RAG (Retrieval-Augmented Generation · 검색 증강 생성)",
