  "w14-q1-why": "슬라이드 19쪽 출석 퀴즈 정답은 'RAG (Retrieval-Augmented Generation · 검색 증강 생성)'입니다! 외부/내부 신뢰 문서를 먼저 검색(Retrieve)한 뒤 답변을 생성(Generate)하여 환각을 예방합니다.",
  "w14-q2-q": "Q2. 기존 데이터를 분석해 '이 사진은 고양이다(98%)'처럼 정답 라벨을 맞히는 모델과, 프롬프트 조건을 바탕으로 '우주에서 커피 마시는 로봇'처럼 세상에 없던 새로운 결과물을 창조하는 모델의 올바른 짝은?",
