  "w14-q2-b": "정답 분류: 판별 모델 (Discriminative Model) / 새로운 창조: 생성 모델 (Generative Model)",
  "w14-q2-why": "데이터가 무엇인지 분류하는 것은 판별 모델(Discriminative Model)이고, 조건을 바탕으로 새로운 글·그림을 창조하는 것은 생성 모델(Generative Model)입니다!",
  "w14-q3-q": "Q3. 이미지를 생성하는 두 기술 중, 위조지폐범 역할의 '생성자(Generator)'와 경찰 역할의 '판별자(Discriminator)'가 서로 경쟁하는 모델과, 무작위 노이즈 점들에서 시작해 단계별로 노이즈를 지워나가며(Denoising) 그림을 조각하는 최신 모델은?",
  "w14-q3-a": "경쟁 모델: STT / 노이즈 제거 모델: One-Hot Encoding",
