  "w14-q3-why": "GAN은 생성자와 판별자가 경쟁하며 학습하고, Diffusion은 노이즈를 단계적으로 제거해 이미지를 생성합니다. 생성 분포와 실제 데이터 분포가 같은 이상적 균형에서는 최적 판별자의 출력이 0.5가 됩니다. 그러나 실제 학습이 항상 이 균형에 수렴하는 것은 아니며, 판별 정확도 50%만으로 생성 품질을 판단할 수 없습니다.",
  "w14-q4-q": "Q4. 'The animal didn't cross the street because it was too tired.'에서 단어 사이 관계를 계산하는 핵심 기술과, 수업에서 소개한 대화형 LLM 훈련의 대표적 순서로 올바른 짝은?",
