  "w14-s1-desc": "Повтор 13-й недели: сеть CNN важна в компьютерном зрении, потому что <b>b) CNN сама изучает признаки и пространственные паттерны изображений</b>, а цель аугментации данных — <b>c) создать больше тренировочных вариантов и повысить качество модели</b>! Теперь переходим к <b>генеративному ИИ (Generative AI)</b>.",
  "w14-disc-badge": "Discriminative Model · Распознавание и классификация",
