  "w14-gen-body": "• Понимает свойства данных и по текстовому промпту создаёт <b>совершенно новые тексты, изображения, музыку и видео</b>.<br>• Пример: генерация картины «Милый робот пьёт кофе в космосе».",
  "w14-sim1-title": "🎨 Примеры промптов: объект + действие + фон + стиль",
  "w14-sim1-desc": "Каждая кнопка показывает подготовленный пример изменения промпта и пояснение ожидаемого эффекта. Эта страница не создаёт изображения и не пересчитывает пиксели в реальном времени.",
  "w14-sim1-btn1": "Шаг 1 [Target Объект]: \"A cute robot\"",
  "w14-sim1-btn2": "Шаг 2 +[Action Действие]: \"Drinking coffee\"",
  "w14-sim1-btn3": "Шаг 3 +[Context Фон]: \"In outer space\"",
  "w14-sim1-btn4": "Шаг 4 +[Style Стиль]: \"In a watercolor style\"",
  "w14-sim1-out1": "🤖 Шаг 1 [Target Объект]: \"A cute robot (Милый робот)\" → Ожидаемый эффект: робот задан как объект изображения. Действие и фон пока не уточнены.",
  "w14-sim1-out2": "☕ Шаг 2 +[Action Действие]: \"A cute robot drinking coffee\" → Ожидаемый эффект: добавлено действие «пить кофе». Это может задать позу, в которой робот держит чашку или пьёт из неё.",
  "w14-sim1-out3": "🪐 Шаг 3 +[Context Фон]: \"A cute robot drinking coffee in outer space\" → Ожидаемый эффект: задан космический фон, который может включать звёзды, планеты и ощущение невесомости.",
  "w14-sim1-out4": "🖌️ Шаг 4 +[Style Стиль]: \"... in a watercolor style (в стиле акварели)\" → Ожидаемый эффект: запрошены мягкая акварельная текстура, плавные переходы цвета и мазки кисти.",
  "w14-s2-title": "2. Четыре ключевые технологии генеративного ИИ: Attention · LLM · GAN · Diffusion",
  "w14-s2-desc": "Разберём, как <b>Attention и LLM</b> понимают и пишут текст, а <b>GAN и диффузионные модели</b> создают изображения.",
  "w14-att-badge": "Ядро Transformer · Взгляд на всё предложение сразу",
  "w14-att-title": "① Механизм внимания (Attention) и большие языковые модели (LLM)",
  "w14-att-body": "• <b>Attention:</b> охватывает всё предложение целиком и вычисляет математическую близость всех слов. Во фразе <i>\"The animal didn't cross the street because <b>it</b> was too tired.\"</i> ИИ точно понимает, что it = animal (животное), а не улица!<br>• <b>LLM (ChatGPT, Gemini):</b> прочитав миллиарды предложений, модель учится <b>угадывать наиболее вероятное следующее слово</b> (\"The weather today is...\" → Good [80%], Cold [15%], Hot [5%]).",
  "w14-llm-badge": "Как создаются умные и вежливые языковые модели",
