  "w14-tbl-col1": "Модель генерации изображений",
  "w14-tbl-col2": "Главная идея и аналогия",
  "w14-tbl-col3": "Принцип работы и критерий готовности",
  "w14-r1-c1": "③ GAN (Генеративно-состязательная сеть)",
  "w14-r1-c2": "<b>Фальшивомонетчик (Generator) против Полицейского (Discriminator)!</b><br>Две нейросети соревнуются друг с другом",
  "w14-r1-c3": "• <b>Генератор:</b> создаёт поддельные картинки, пытаясь обмануть систему.<br>• <b>Дискриминатор:</b> пытается отличить настоящие фото от подделок.<br>• <b>Итог обучения:</b> обучение завершается, когда вероятность угадывания у дискриминатора сходится к <b>50% (как бросок монетки)</b>!",
  "w14-r2-c1": "④ Diffusion (Диффузионная модель)",
  "w14-r2-c2": "<b>Создание скульптуры из облака случайного шума!</b><br>Главный современный метод генерации арт-изображений",
  "w14-r2-c3": "• <b>Прямой процесс (Разрушение):</b> к чистым фото постепенно добавляется шум (как растворение кубика сахара в воде).<br>• <b>Обратный процесс (Denoising · Очистка от шума):</b> начинает со случайных точек шума и <b>пошагово удаляет шум по условиям промпта</b> до чёткой картины!",
  "w14-sim2-title": "🧠 Сравните наглядно: 4 технологии генеративного ИИ (Attention · LLM · GAN · Diffusion)",
