  "w14-sim2-btn1": "1. Attention ('it = animal')",
  "w14-sim2-btn2": "2. LLM (Вероятность следующего слова и 3 этапа)",
  "w14-sim2-btn3": "3. GAN (Фальшивомонетчик vs Судья · 50%)",
  "w14-sim2-btn4": "4. Diffusion (Пошаговое удаление шума)",
  "w14-sim2-out1": "🕸️ Attention (Внимание): во фразе \"The animal didn't cross the street because it was too tired\" модель видит всё предложение сразу и связывает местоимение 'it' со словом 'animal (животное)', так как дорога устать не может.",
  "w14-sim2-out2": "📊 LLM (Большая языковая модель): вычисляет вероятность следующего слова (Good 80%, Cold 15%, Hot 5%) и проходит 3 этапа обучения: Pre-training → Fine-tuning → RLHF.",
  "w14-sim2-out3": "⚔️ GAN: Генератор и Дискриминатор соревнуются десятки тысяч раз, пока подделки не станут настолько реалистичными, что точность Дискриминатора снизится до 50% (уровень броска монетки)!",
  "w14-sim2-out4": "🌫️➡️🖼️ Diffusion (Диффузия): изучает процесс зашумления фото, а при генерации действует наоборот — шаг за шагом очищает случайный шум (Denoising) по инструкции промпта, словно высекая скульптуру из тумана!",
