  "w14-sim3-btn1": "1. Обычный LLM (Только память весов → Галлюцинация!)",
  "w14-sim3-btn2": "2. Архитектура RAG (Поиск в базе знаний → Точный ответ!)",
  "w14-sim3-out1": "⚠️ Обычный LLM (Высокий риск галлюцинации): полагается только на внутреннюю память и может уверенно выдумать ложный факт (например, «Луна сделана из зелёного сыра» или несуществующее правило отпуска).",
  "w14-sim3-out2": "✅ RAG (Retrieval-Augmented Generation · Ответ на тест посещаемости!): 1) Сначала ищет достоверные документы во внешней/внутренней базе знаний (Specific Knowledge Base) → 2) Объединяет вопрос с найденным документом → 3) Генерирует точный ответ со ссылкой на источник! (3 плюса: Точность, Актуальность без переобучения модели, Безопасность корпоративных данных)",
