  "itbasics-g1-title": "기기·화면·앱",
  "itbasics-g1-summary": "손으로 만지는 기기와 그 안에서 사용하는 프로그램을 구분합니다.",
  "itbasics-g1-item1-title": "하드웨어 (Hardware)",
  "itbasics-g1-item1-body": "손으로 만질 수 있는 기기와 부품입니다. 노트북, 화면, 키보드, 마우스가 예입니다.",
