  "itbasics-help-title": "막혔을 때 이렇게 말해 보세요",
  "itbasics-help-body": "기기 이름, 마지막으로 누른 버튼, 화면에 나온 문구를 알려주면 도움을 받기 쉽습니다. 비밀번호나 인증번호는 보여주지 않아도 됩니다.",
  "itbasics-help-phrase1": "“이 화면에서 다음에 무엇을 눌러야 하나요?”",
  "itbasics-help-phrase2": "“이 단어의 뜻을 쉬운 예로 설명해 주세요.”",
  "itbasics-skip-link": "기기 사용이 익숙하면 수업 목표 살펴보기 ↓",
  "itpractice-title": "직접 해보기 · 버튼, 글자, 복사",
