  "itpractice-note": "이 연습은 입력한 글을 서버에 보내거나 별도로 저장하지 않습니다. 언어를 바꿔도 글은 유지됩니다. 새로고침하면 사라질 수 있습니다.",
  "itpractice-tap-title": "버튼을 눌러 보기",
