  "itpractice-type-title": "빈칸에 글자 쓰기",
  "itpractice-type-help": "아래 빈칸을 먼저 누르세요. 키보드에서 영어 A와 I를 입력한 뒤 확인을 누르세요. Enter 키로도 확인할 수 있어요.",
  "itpractice-type-label": "여기에 AI를 써 보세요",
