  "itpractice-paste-done": "예시와 같은 AI가 들어왔어요. 복사한 글자는 다른 빈칸에도 붙여넣을 수 있어요.",
  "itpractice-paste-empty": "아직 글자가 없어요. 먼저 AI를 복사하고, 이 빈칸을 누른 뒤 붙여넣으세요.",
  "itpractice-paste-retry": "다른 글자가 들어왔어요. 위의 AI를 다시 복사한 뒤 이 빈칸에 붙여넣어 보세요.",
